from boltons.excutils import ExceptionCauseMixin

class E(ExceptionCauseMixin):
    pass

def test_it():
    try:
        try:
            raise ValueError('x')
        except ValueError as ve:
            raise E(ve, 'm')
    except E as e:
        s = str(e)
    assert 'Wrapped traceback' in s
    assert 'caused by ValueError' in s
